  function ingredientMatches(a,b){const x=ingredientName(a),y=ingredientName(b);if(!x||!y)return false;return x===y||x.includes(y)||y.includes(x)||x.split(' ').some(w=>w.length>3&&y.includes(w))}
  function groceryCategory(text){const s=ingredientName(text);if(/apple|banana|berry|strawber|lemon|lime|orange|tomato|onion|garlic|carrot|cabbage|spinach|lettuce|broccoli|pepper|potato|mushroom|cucumber|ginger|scallion|green onion|herb/.test(s))return'Produce';if(/chicken|beef|pork|fish|salmon|tuna|shrimp|tofu|egg/.test(s))return'Protein';if(/milk|cream|cheese|butter|yogurt/.test(s))return'Dairy & Eggs';if(/rice|flour|sugar|salt|oil|sauce|vinegar|noodle|pasta|bread|crumb|miso|nori|spice|stock|broth/.test(s))return'Pantry';return'Other'}
