  function tomorrowPrepItems(){const d=new Date();d.setDate(d.getDate()+1);const key=dateKey(d),plan=state.mealPlan[key]||{},items=[];for(const slot of activeMealSlots()){const item=plan[slot];if(!item)continue;if(item.prepNote)items.push({icon:'📝',title:item.prepNote,sub:`For ${slot}`});const r=getRecipe(item.recipeId);if(!r)continue;const freezerMatches=state.pantry.filter(p=>p.location==='Freezer'&&(r.ingredients||[]).some(i=>ingredientMatches(i,p.name)));freezerMatches.forEach(p=>items.push({icon:'❄️',title:`Move ${p.name} from freezer`,sub:`For ${r.title}` }));if((r.steps||[]).some(s=>/marinat|soak|overnight/i.test(s)))items.push({icon:'🥣',title:`Check make-ahead step for ${r.title}`,sub:'Marinating, soaking or overnight prep may help'});if(totalTime(r)>=60)items.push({icon:'⏰',title:`Allow about ${totalTime(r)} min for ${r.title}`,sub:`Tomorrow ${slot}`})}const seen=new Set();return items.filter(x=>{const k=x.title.toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).slice(0,10)}
  function preferredSlotForRecipe(r){const c=String(r?.category||'').toLowerCase();if(c==='breakfast'&&activeMealSlots().includes('breakfast'))return'breakfast';if(c==='lunch'&&activeMealSlots().includes('lunch'))return'lunch';if(/snack|dessert|sweets|fried & street food/.test(c)&&activeMealSlots().includes('snack'))return'snack';return activeMealSlots().includes('dinner')?'dinner':activeMealSlots()[0]}
  function planRecipeNextAvailable(recipeId){const r=getRecipe(recipeId);if(!r)return;const preferred=preferredSlotForRecipe(r),slots=[preferred,...activeMealSlots().filter(s=>s!==preferred)];for(let i=0;i<14;i++){const d=new Date();d.setDate(d.getDate()+i);const k=dateKey(d);state.mealPlan[k]||={};for(const slot of slots){if(!state.mealPlan[k][slot]){state.mealPlan[k][slot]={recipeId:r.id,servings:r.servings||state.settings.defaultServings||2,prepNote:'',extraPortions:0};const undo=()=>{if(state.mealPlan[k]){delete state.mealPlan[k][slot];if(!Object.keys(state.mealPlan[k]).length)delete state.mealPlan[k]}};commit();toast(`Planned ${r.title} for ${formatLongDate(d)} ${slot}`,undo);return}}if(!Object.keys(state.mealPlan[k]).length)delete state.mealPlan[k]}toast('No empty meal slot found in the next two weeks')}
  function suggestMealSwap(){if(!state.recipes.length){toast('Add another recipe before using meal swap');return}const currentId=$('#mealRecipeSelect')?.value||'',current=getRecipe(currentId),slot=$('#mealSlotInput')?.value||'dinner',ctx=createMatchContext();let candidates=standardRecipePool().filter(r=>r.id!==currentId);if(current?.category)candidates.sort((a,b)=>Number(b.category===current.category)-Number(a.category===current.category));const ranked=candidates.map(r=>({r,m:recipeMatch(r,[],ctx)})).sort((a,b)=>b.m.useSoon-a.m.useSoon||b.m.percent-a.m.percent||totalTime(a.r)-totalTime(b.r));const pick=ranked[0]?.r;if(!pick){toast('No alternative recipe found');return}$('#mealRecipeSelect').value=pick.id;$('#mealCustomInput').value='';$('#mealServingsInput').value=pick.servings||state.settings.defaultServings||2;toast(`Swap suggestion: ${pick.title}`)}
  function updateLowStockState(p){if(p?.lowThreshold!=null&&Number.isFinite(Number(p.lowThreshold)))p.lowStock=Number(p.quantity||0)<=Number(p.lowThreshold)}
  function ensureRecurringStaples(showToast=false){if(!state.settings.autoStapleGroceries)return 0;let n=0;for(const p of state.pantry){updateLowStockState(p);if(!p.staple||!p.lowStock)continue;if(!state.grocery.some(g=>!g.checked&&ingredientMatches(g.ingredientName||g.text,p.name))){state.grocery.push({id:uid('g'),text:p.name,checked:false,category:groceryCategory(p.name),source:'recurring-staple'});n++}}if(n){queuePersist();if(showToast)toast(`${n} staple${n===1?'':'s'} added to groceries`)}return n}
  function aggregateWeekRequirements(){const map=new Map();for(const d of weekDates()){const day=state.mealPlan[dateKey(d)]||{};for(const slot of MEAL_SLOTS){const item=day[slot],r=getRecipe(item?.recipeId);if(!r)continue;const factor=(Number(item.servings)||Number(r.servings)||1)/(Number(r.servings)||1);for(const line of r.ingredients||[]){const p=parseIngredient(line);if(!p.name)continue;const key=`${p.name}|${p.baseUnit||'unknown'}`,entry=map.get(key)||{name:p.name,baseUnit:p.baseUnit||'',displayUnit:p.displayUnit||p.unit||'',qty:0,known:true,sources:new Set(),example:line};if(Number.isFinite(p.baseQty))entry.qty+=p.baseQty*factor;else entry.known=false;entry.sources.add(r.title);map.set(key,entry)}}}return [...map.values()]}
  function pantryAvailability(req){const matches=state.pantry.filter(p=>ingredientMatches(p.name,req.name));let total=0,compatible=false,packageItem=matches.find(p=>p.packageSize)||matches[0];for(const p of matches){const b=toBaseQty(p.quantity,p.unit);if(b&&req.baseUnit&&b.baseUnit===req.baseUnit){total+=b.value;compatible=true}else if(!req.baseUnit&&Number(p.quantity)>0){compatible=true;total+=Number(p.quantity)}}return{matches,total,compatible,packageItem}}
