  function planAroundExpiry(){const exp=expiringIngredientNames(),ctx=createMatchContext();if(!exp.length){toast('Nothing in your pantry is expiring soon');return}const pick=standardRecipePool().map(r=>({r,m:recipeMatch(r,[],ctx)})).filter(x=>x.m.useSoon>0).sort((a,b)=>b.m.useSoon-a.m.useSoon||b.m.percent-a.m.percent||totalTime(a.r)-totalTime(b.r))[0];if(!pick){toast('No saved recipe uses the expiring ingredients yet');return}planRecipeNextAvailable(pick.r.id)}
  function renderParallelTimeline(){const date=$('#parallelDate')?.value||dateKey(new Date()),time=$('#parallelTime')?.value||state.settings.defaultDinnerTime||'19:00',out=$('#parallelOutput');if(!out)return;const plan=state.mealPlan[date]||{},recipes=activeMealSlots().map(slot=>({slot,item:plan[slot],r:getRecipe(plan[slot]?.recipeId)})).filter(x=>x.r);if(!recipes.length){out.innerHTML='<p class="muted" style="margin-top:10px">Plan saved recipes on that date first.</p>';return}const [hh,mm]=time.split(':').map(Number),ready=parseDate(date)||new Date();ready.setHours(hh,mm,0,0);const fmt=d=>d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}),rows=recipes.map(x=>{const prep=Number(x.r.prep||0),cook=Number(x.r.cook||0),start=new Date(ready.getTime()-(prep+cook)*60000),cookStart=new Date(ready.getTime()-cook*60000);return{...x,start,cookStart}}).sort((a,b)=>a.start-b.start);out.innerHTML=`<div class="detail-section"><h3>Everything ready by ${fmt(ready)}</h3>${rows.map(x=>`<div class="timeline-card"><div class="timeline-card-head"><div><b>${foodEmoji(x.r)} ${esc(x.r.title)}</b><small class="muted">${esc(x.slot)} · ${totalTime(x.r)} min total</small></div><strong>${fmt(x.start)}</strong></div><small class="muted">Prep ${fmt(x.start)} · cook ${fmt(x.cookStart)} · serve ${fmt(ready)}</small></div>`).join('')}</div>`}
  function renderIngredientJourney(){const term=($('#journeyIngredientInput')?.value||'').trim(),out=$('#journeyOutput');if(!out)return;if(!term){out.innerHTML='<p class="muted" style="margin-top:10px">Type an ingredient to trace it through your week and recipe library.</p>';return}const planned=[];weekDates().forEach(d=>{const day=state.mealPlan[dateKey(d)]||{};for(const slot of MEAL_SLOTS){const r=getRecipe(day[slot]?.recipeId);if(r&&(r.ingredients||[]).some(i=>ingredientMatches(i,term)))planned.push({date:d,slot,r})}});const library=standardRecipePool().filter(r=>(r.ingredients||[]).some(i=>ingredientMatches(i,term))).slice(0,20);out.innerHTML=`<div class="detail-section"><h3>🥕 ${esc(term)}</h3><p class="muted">This week</p>${planned.length?planned.map(x=>`<div class="journey-use"><time>${esc(formatShortDate(x.date))}</time><button class="text-btn" data-recipe-id="${x.r.id}">${esc(x.r.title)}</button><small class="muted">${esc(x.slot)}</small></div>`).join(''):'<p class="muted">Not used in this visible week.</p>'}<p class="muted" style="margin-top:12px">Saved recipes</p>${library.length?library.map(r=>`<button class="list-card" data-recipe-id="${r.id}"><span class="emoji">${foodEmoji(r)}</span><span class="content"><b>${esc(r.title)}</b><small>${totalTime(r)} min</small></span><span class="meta">›</span></button>`).join(''):'<p class="muted">No saved recipe uses it yet.</p>'}</div>`}
  function preparePantryDeductions(r,factor=1){const byPantry=new Map();for(const line of r.ingredients||[]){const pi=parseIngredient(line),p=state.pantry.find(x=>Number(x.quantity)>0&&ingredientMatches(x.name,pi.name));if(!p)continue;let amount=1;if(Number.isFinite(pi.baseQty)){const pb=toBaseQty(p.quantity,p.unit),def=unitDef(p.unit);if(pb&&def&&pb.baseUnit===pi.baseUnit)amount=fromBaseQty(pi.baseQty*Math.max(.01,Number(factor)||1),p.unit)}amount=Math.min(Number(p.quantity)||0,Math.max(.01,Number(amount)||1));const ex=byPantry.get(p.id);if(ex)ex.amount=Math.min(Number(p.quantity)||0,ex.amount+amount);else byPantry.set(p.id,{pantryId:p.id,name:p.name,amount,unit:p.unit||'',before:Number(p.quantity)||0})}pendingPantryDeductions=[...byPantry.values()];return pendingPantryDeductions}
