  function renderActivity(){const purchases=[...state.purchaseHistory].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,100),uses=[...state.useHistory].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,100);const row=(x,icon,verb)=>`<div class="activity-row"><span>${icon}</span><span><b>${esc(x.item||x.name||'Item')}</b><small>${esc(verb)}${x.amount!=null?` · ${prettyQty(Number(x.amount))} ${esc(x.unit||'')}`:''}</small></span><time>${esc(formatDateTime(x.date))}</time></div>`;$('#purchaseHistoryList').innerHTML=purchases.length?purchases.map(x=>row(x,'🧺','Added to pantry')).join(''):emptyCard('Nothing bought has been logged yet. Checked groceries appear here only after you move them to Pantry.');$('#pantryUseHistoryList').innerHTML=uses.length?uses.map(x=>row(x,'🥣','Used from pantry')).join(''):emptyCard('No pantry use recorded yet. Bento only logs amounts you confirm after cooking.')}

  function navigate(view,pushHash=true){if(view==='more')view='home';if(view!=='grocery'&&document.body.classList.contains('shopping-mode')){document.body.classList.remove('shopping-mode');$('#shoppingModeButton')?.setAttribute('aria-pressed','false');if(!cookingSession)releaseWakeLock()}if(!document.querySelector(`.view[data-view="${view}"]`))view='home';closeMenu();if(currentView!==view)previousView=currentView;currentView=view;$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===view));$$('.bottom-nav button').forEach(b=>{const on=b.dataset.nav===view;b.classList.toggle('active',on);on?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')});if(pushHash&&location.hash!==`#${view}`)history.pushState({view},'',`#${view}`);window.scrollTo(0,0);$('#mainContent')?.focus({preventScroll:true});try{renderCurrentView()}catch(err){console.error('Bento navigation render error',err)}try{renderGlobalBadges()}catch(err){console.warn('Bento badge refresh skipped',err)}try{observePhotos()}catch(err){console.warn('Bento photo refresh skipped',err)}}
  function back(){navigate(previousView||'home')}
  function openMenu(){const menu=$('#appMenu'),backdrop=$('#menuBackdrop');if(!menu||!backdrop)return;backdrop.hidden=false;requestAnimationFrame(()=>{menu.classList.add('open');backdrop.classList.add('open')});menu.setAttribute('aria-hidden','false');$('#menuButton')?.setAttribute('aria-expanded','true');document.body.classList.add('menu-open')}
  function closeMenu(){const menu=$('#appMenu'),backdrop=$('#menuBackdrop');if(!menu||!backdrop)return;menu.classList.remove('open');backdrop.classList.remove('open');menu.setAttribute('aria-hidden','true');$('#menuButton')?.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open');setTimeout(()=>{if(!backdrop.classList.contains('open'))backdrop.hidden=true},210)}

  function updateGroceryCounters(){const unchecked=state.grocery.reduce((n,g)=>n+(!g.checked?1:0),0),checked=state.grocery.length-unchecked,estimate=state.grocery.reduce((n,g)=>n+(Number(g.price)||0),0);if($('#groceryUnchecked'))$('#groceryUnchecked').textContent=unchecked;if($('#groceryChecked'))$('#groceryChecked').textContent=checked;if($('#groceryEstimate')){try{$('#groceryEstimate').textContent=estimate?estimate.toLocaleString(undefined,{style:'currency',currency:state.settings.currency||'PHP'}):'—'}catch{$('#groceryEstimate').textContent=estimate?String(estimate):'—'}}const badge=$('#groceryNavBadge');if(badge){badge.textContent=unchecked>99?'99+':String(unchecked);badge.classList.toggle('hidden',unchecked===0)}}
  function renderGlobalBadges(){
    const unchecked=state.grocery.reduce((n,g)=>n+(!g.checked?1:0),0);
    if($('#groceryCountQuick'))$('#groceryCountQuick').textContent=`${unchecked} item${unchecked===1?'':'s'}`;
    if($('#pantryCountQuick'))$('#pantryCountQuick').textContent=`${state.pantry.length} item${state.pantry.length===1?'':'s'}`;
    updateGroceryCounters();
  }
  function renderGreeting(){const h=new Date().getHours(),g=h<12?'Good morning':h<18?'Good afternoon':'Good evening',name=(state.settings.displayName||'').trim();$('#greetingText').textContent=`${g}${name?`, ${name}`:''} ✿`}
  function renderHome(){
    renderGreeting();const firstRun=isFirstRun();$('#firstRunWelcome')?.classList.toggle('hidden',!firstRun);
    const today=dateKey(new Date()),plan=state.mealPlan[today]||{},slots=activeMealSlots();
    $('#todayMeals').innerHTML=slots.map(slot=>{const item=plan[slot];let title='Nothing planned',sub='Tap to add';if(item?.recipeId){const r=getRecipe(item.recipeId);if(r){title=r.title;sub=`${totalTime(r)} min · ${item.servings||r.servings||2} servings${item.extraPortions?` · +${item.extraPortions} leftover`:''}`}}else if(item?.custom){title=item.custom;sub=item.prepNote||'Custom meal'}return `<button class="meal-card" data-meal-date="${today}" data-meal-slot="${slot}"><span class="meal-slot">${slot}</span><span class="meal-main"><b>${esc(title)}</b><small>${esc(sub)}</small></span><span class="arrow">›</span></button>`}).join('');
    const prep=tomorrowPrepItems(),showPrep=!firstRun&&state.settings.showTomorrowPrep!==false&&prep.length>0;$('#tomorrowPrepHeading')?.classList.toggle('hidden',!showPrep);$('#tomorrowPrep')?.classList.toggle('hidden',!showPrep);if(showPrep)$('#tomorrowPrep').innerHTML=prep.length?prep.map(x=>`<div class="prep-card"><span>${x.icon}</span><div><b>${esc(x.title)}</b><small>${esc(x.sub)}</small></div></div>`).join(''):emptyCard('Nothing needs advance prep for tomorrow.');
    $('#homeQuickActions')?.classList.toggle('hidden',!firstRun&&state.settings.showHomeQuickActions===false);
    const weekMeals=weekDates(0).reduce((n,d)=>n+Object.keys(state.mealPlan[dateKey(d)]||{}).length,0),expiring=state.pantry.filter(p=>{const d=daysUntil(p.expiry);return d>=0&&d<=expiryWindow()}).length,monthStart=new Date();monthStart.setDate(1);monthStart.setHours(0,0,0,0);const cookedMonth=state.history.filter(h=>new Date(h.date)>=monthStart).length;
    $('#homeStats').innerHTML=`<div class="stat-card"><strong>${weekMeals}</strong><small>meals planned</small></div><div class="stat-card"><strong>${cookedMonth}</strong><small>cooked this month</small></div><div class="stat-card"><strong>${expiring}</strong><small>use soon</small></div>`;
    const showStats=!firstRun&&state.settings.showHomeStats!==false;$('#homeStats')?.classList.toggle('hidden',!showStats);$('#homeStatsHeading')?.classList.toggle('hidden',!showStats);renderAttention();
    const showFav=!firstRun&&state.settings.showHomeFavorites!==false;$('#homeFavorites')?.classList.toggle('hidden',!showFav);$('#homeFavoritesHeading')?.classList.toggle('hidden',!showFav);if(showFav){const favs=standardRecipePool().filter(r=>r.favorite).slice(0,6);$('#homeFavorites').innerHTML=favs.length?favs.map(recipeMini).join(''):emptyCard('Heart recipes you love and they’ll appear here.','Browse recipes','go-recipes')}
  }

  function renderAttention(){const expiring=state.pantry.filter(p=>{const d=daysUntil(p.expiry);return d>=0&&d<=expiryWindow()}).sort((a,b)=>daysUntil(a.expiry)-daysUntil(b.expiry));const low=state.pantry.filter(p=>p.lowStock),unchecked=state.grocery.filter(g=>!g.checked).length,leftSoon=state.leftovers.filter(l=>{const d=daysUntil(l.useBy);return d>=0&&d<=2}).length;const c=[];if(expiring.length)c.push(`<button class="attention-card" data-view-link="smart" data-auto-tool="rescue"><span class="dot"></span><div><b>${expiring.length} pantry item${expiring.length>1?'s':''} expiring soon</b><small>${esc(expiring.slice(0,3).map(x=>x.name).join(', '))}</small></div><span>›</span></button>`);if(leftSoon)c.push(`<button class="attention-card" data-view-link="leftovers"><span class="dot"></span><div><b>${leftSoon} leftover${leftSoon>1?'s':''} to use soon</b><small>Eat, freeze or plan them next</small></div><span>›</span></button>`);if(low.length)c.push(`<button class="attention-card" data-nav="pantry"><span class="dot"></span><div><b>${low.length} low-stock item${low.length>1?'s':''}</b><small>Restock when convenient</small></div><span>›</span></button>`);if(unchecked)c.push(`<button class="attention-card" data-nav="grocery"><span class="dot"></span><div><b>${unchecked} grocery item${unchecked>1?'s':''} waiting</b><small>Open your shopping list</small></div><span>›</span></button>`);$('#attentionCards').innerHTML=c.join('')||emptyCard('Nothing urgent right now. Your kitchen is looking tidy ✿')}
  function recipeMini(r){return `<button class="mini-recipe" data-recipe-id="${r.id}"><b>${foodEmoji(r)} ${esc(r.title)}</b><small>${totalTime(r)} min · ${esc(r.category||'Other')}</small></button>`}

  function renderPlan(){const dates=weekDates(),todayKey=dateKey(new Date());$('#weekLabel').textContent=`${formatShortDate(dates[0])} – ${formatShortDate(dates[6])}`;$('#weekDays').innerHTML=dates.map(d=>`<div class="day-pill ${dateKey(d)===todayKey?'today':''}"><b>${d.toLocaleDateString(undefined,{weekday:'short'})}</b><span>${d.getDate()}</span></div>`).join('');const planned=[];for(const d of dates){const key=dateKey(d),day=state.mealPlan[key]||{};for(const slot of activeMealSlots()){const item=day[slot],r=getRecipe(item?.recipeId);if(r)planned.push({key,d,slot,item,r})}}const summary=planned.length?`<section class="plan-week-summary"><div class="plan-summary-head"><div><p class="eyebrow">This week</p><h3>Planned recipes</h3></div><small>${planned.length} meal${planned.length===1?'':'s'}</small></div><div class="plan-summary-list">${planned.map(x=>`<button type="button" class="plan-summary-recipe" data-recipe-id="${x.r.id}" data-recipe-serving="${Number(x.item.servings)||Number(x.r.servings)||2}"><span>${foodEmoji(x.r)}</span><span><b>${esc(x.r.title)}</b><small>${esc(x.d.toLocaleDateString(undefined,{weekday:'short'}))} · ${esc(x.slot)} · ${Number(x.item.servings)||Number(x.r.servings)||2} servings</small></span><i>›</i></button>`).join('')}</div></section>`:'';const days=dates.map(d=>{const key=dateKey(d),day=state.mealPlan[key]||{};return `<article class="plan-day"><div class="plan-day-head"><b>${esc(formatLongDate(d))}</b><small>${key===todayKey?'Today':''}</small></div>${activeMealSlots().map(slot=>{const item=day[slot];if(item?.recipeId){const r=getRecipe(item.recipeId);if(r){const sv=Number(item.servings)||Number(r.servings)||2,sub=`${totalTime(r)} min · ${sv} servings${item.prepNote?` · ${item.prepNote}`:''}${item.extraPortions?` · +${item.extraPortions} leftover${item.extraPortions===1?'':'s'}`:''}`;return `<div class="plan-slot filled"><span>${slot}</span><button type="button" class="plan-slot-recipe" data-recipe-id="${r.id}" data-recipe-serving="${sv}"><b>${esc(r.title)}</b><small>${esc(sub)}</small></button><button type="button" class="plan-slot-edit" data-meal-date="${key}" data-meal-slot="${slot}" aria-label="Edit ${esc(slot)}">•••</button></div>`}}if(item?.custom)return `<div class="plan-slot filled"><span>${slot}</span><button type="button" class="plan-slot-recipe" data-meal-date="${key}" data-meal-slot="${slot}"><b>${esc(item.custom)}</b><small>${esc(item.prepNote||'Custom meal')}</small></button><button type="button" class="plan-slot-edit" data-meal-date="${key}" data-meal-slot="${slot}" aria-label="Edit ${esc(slot)}">•••</button></div>`;return `<button type="button" class="plan-slot empty" data-meal-date="${key}" data-meal-slot="${slot}"><span>${slot}</span><div><b>Add meal</b></div><i class="plan-add">+</i></button>`}).join('')}</article>`}).join('');$('#mealPlanGrid').innerHTML=summary+days}

  function recipeGameAppearances(r){return Array.isArray(r?.gameAppearances)?r.gameAppearances.filter(a=>a&&typeof a==='object'):[]}
