  function activeGameAppearance(r){if(recipeBrowseMode!=='games')return null;const apps=recipeGameAppearances(r);if(!apps.length)return null;const wantedRegion=recipeFilter.startsWith('GenshinRegion:')?recipeFilter.slice(14):'';const wantedSeries=recipeFilter.startsWith('Collection:')?recipeFilter.slice(11):'Genshin Impact';return apps.find(a=>(!wantedSeries||a.series===wantedSeries)&&(!wantedRegion||a.region===wantedRegion))||apps[0]}
