  function clearRecipeFilters(){const defaults={cuisines:'Cuisines',meals:'Meals',desserts:'Type:desserts',drinks:'Type:drinks',games:'Games',anime:'Anime'};recipeFilter=defaults[recipeBrowseMode]||'All';recipeCuisineFilter='All';recipeRenderLimit=RECIPE_RENDER_BATCH;const q=$('#recipeSearch');if(q)q.value='';renderRecipes()}
