      if(grid)grid.innerHTML=f.length?fv.map(recipeCard).join('')+(f.length>fv.length?`<div class="load-more-wrap"><button class="soft-btn load-more-btn" data-load-more-recipes>Show more · ${f.length-fv.length} remaining</button></div>`:''):emptyCard('No favorites yet. Tap ♡ on a recipe you love.','Browse recipes','go-recipes');
