  $('#quickAddButton').addEventListener('click',()=>openDialog($('#quickAddDialog')));$('#brandButton').addEventListener('click',()=>navigate('about'));$('#searchButton').addEventListener('click',()=>{navigate('recipes');const input=$('#recipeSearch');if(input){try{input.focus({preventScroll:true});input.setSelectionRange(input.value.length,input.value.length)}catch{input.focus()}input.scrollIntoView({block:'center'})}});
  $('#menuButton').addEventListener('click',openMenu);$('#menuCloseButton').addEventListener('click',closeMenu);$('#menuBackdrop').addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#appMenu')?.classList.contains('open'))closeMenu()});

  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('#installButton').classList.remove('hidden')});$('#installButton').addEventListener('click',async()=>{if(!deferredInstallPrompt){toast('On iPhone: Share → Add to Home Screen');return}deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;$('#installButton').classList.add('hidden')});window.addEventListener('appinstalled',()=>toast('Bento installed ♡'));if(/iPhone|iPad|iPod/i.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches)$('#installButton').classList.remove('hidden');

