  $$('dialog').forEach(d=>d.addEventListener('close',()=>{if(d.id==='recipeDetailDialog'){cookingSession=null;stopCookingTimer(false);releaseWakeLock();recipeDetailId='';recipeDetailServingTarget=null;recipeDetailChecked.clear();try{sessionStorage.removeItem(OPEN_RECIPE_SESSION_KEY)}catch{}}}));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persistNow();else{if(cookingTimer)syncCookingTimer();if(cookingSession||document.body.classList.contains('shopping-mode'))requestWakeLock()}});window.addEventListener('pagehide',persistNow);
